export const key=(a,b)=>[a,b].sort().join('|');
export function createSeason(players,relations,alliances){return {players:structuredClone(players).map(p=>({...p,wins:0,out:false})),relations:{...relations},alliances:structuredClone(alliances),week:1,stage:'hoh',previous:null,hoh:null,nominees:[],history:[],order:[],winner:null};}
export function advance(s,rng=Math.random){
 const alive=s.players.filter(p=>!p.out),get=id=>s.players.find(p=>p.id===id),name=id=>get(id).name;
 const bond=(a,b)=>(s.relations[key(a,b)]||0)+s.alliances.filter(g=>g.members.includes(a)&&g.members.includes(b)).reduce((n,g)=>n+g.loyalty/2,0);
 const choose=(ps,score)=>ps.map(p=>({p,v:score(p)+rng()*12})).sort((a,b)=>b.v-a.v)[0].p;
 const event=(title,text,ids=[],extra={})=>{const e={week:s.week,stage:s.stage,title,text,ids,...extra};s.history.push(e);return e;};
 if(s.winner)return null;
 if(alive.length===2){const jury=s.order.slice(-Math.min(7,s.order.length)).map(get);const votes=jury.map(j=>({voter:j.id,target:choose(alive,p=>bond(j.id,p.id)+p.wins*1.8+p.strategy*.6+p.social*.4).id}));const tally=alive.map(p=>({p,n:votes.filter(v=>v.target===p.id).length})).sort((a,b)=>b.n-a.n);const win=tally[0].n===tally[1].n?choose(alive,p=>p.wins+p.social):tally[0].p;s.winner=win.id;s.stage='final';return event('Ο μεγάλος τελικός',`${win.name} κερδίζει τη σεζόν! Η κριτική επιτροπή ψήφισε με βάση σχέσεις, νίκες και στρατηγική.`,alive.map(p=>p.id),{votes,tie:tally[0].n===tally[1].n});}
 if(s.stage==='hoh'){const eligible=alive.filter(p=>p.id!==s.previous||alive.length===3);const p=choose(eligible,p=>p.competition*.9+p.strategy*.35);s.hoh=p.id;p.wins++;const e=event(alive.length===3?'Τελικός αρχηγός':'Αγώνας αρχηγού',`${p.name} κερδίζει την εξουσία και την ασυλία της εβδομάδας.`,[p.id]);s.stage=alive.length===3?'finalcut':'nominate';return e;}
 if(s.stage==='finalcut'){const others=alive.filter(p=>p.id!==s.hoh);const out=choose(others,p=>-bond(s.hoh,p.id)+p.strategy*.5+p.wins);out.out=true;s.order.push(out.id);const e=event('Μία θέση πριν τον τελικό',`${name(s.hoh)} επιλέγει να αποχωρήσει ${out.name}. Οι δύο φιναλίστ αντιμετωπίζουν την κριτική επιτροπή.`,[out.id],{evicted:out.id});s.stage='jury';return e;}
 if(s.stage==='nominate'){s.nominees=alive.filter(p=>p.id!==s.hoh).map(p=>({p,v:-bond(s.hoh,p.id)+p.strategy*get(s.hoh).strategy/16+p.wins+rng()*8})).sort((a,b)=>b.v-a.v).slice(0,2).map(x=>x.p.id);const e=event('Τελετή υποψηφιοτήτων',`${name(s.hoh)} θέτει σε κίνδυνο τους ${s.nominees.map(name).join(' και ')}.`,s.nominees);s.stage='veto';return e;}
 if(s.stage==='veto'){const fixed=alive.filter(p=>p.id===s.hoh||s.nominees.includes(p.id));const rest=alive.filter(p=>!fixed.includes(p)).map(p=>({p,v:rng()})).sort((a,b)=>a.v-b.v).slice(0,Math.max(0,6-fixed.length)).map(x=>x.p);const winner=choose([...fixed,...rest],p=>p.competition+p.strategy*.25);winner.wins++;let saved=s.nominees.includes(winner.id)?winner.id:s.nominees.find(id=>bond(winner.id,id)>5);let replacement=null;if(saved){const candidates=alive.filter(p=>p.id!==s.hoh&&p.id!==winner.id&&!s.nominees.includes(p.id));if(candidates.length){replacement=choose(candidates,p=>-bond(s.hoh,p.id)+p.strategy*.4).id;s.nominees=s.nominees.map(id=>id===saved?replacement:id);}else saved=null;}const e=event('Power of Veto',`${winner.name} κερδίζει το veto. ${saved?`${name(saved)} σώζεται και ${name(replacement)} παίρνει τη θέση του.`:'Οι υποψηφιότητες παραμένουν ίδιες.'}`,[winner.id,...s.nominees]);s.stage='house';return e;}
 if(s.stage==='house'){const a=alive[Math.floor(rng()*alive.length)],b=alive.filter(p=>p!==a)[Math.floor(rng()*(alive.length-1))];const delta=rng()>.45?2:-2;const k=key(a.id,b.id);s.relations[k]=Math.max(-10,Math.min(10,(s.relations[k]||0)+delta));const e=event('Μέσα στο σπίτι',delta>0?`${a.name} και ${b.name} έρχονται πιο κοντά μετά από μία ειλικρινή συζήτηση.`:`Ένταση ανάμεσα σε ${a.name} και ${b.name}. Η εμπιστοσύνη τους κλονίζεται.`,[a.id,b.id]);s.stage='evict';return e;}
 if(s.stage==='evict'){const nominees=s.nominees.map(get);const votes=alive.filter(p=>p.id!==s.hoh&&!s.nominees.includes(p.id)).map(p=>({voter:p.id,target:choose(nominees,n=>-bond(p.id,n.id)+n.strategy*p.strategy/20-n.social*.3).id}));const counts=s.nominees.map(id=>({id,n:votes.filter(v=>v.target===id).length})).sort((a,b)=>b.n-a.n);const tie=counts[0].n===counts[1].n;const out=tie?choose(nominees,p=>-bond(s.hoh,p.id)+p.strategy*.3).id:counts[0].id;get(out).out=true;s.order.push(out);const e=event('Η ώρα της αποχώρησης',`${name(out)}, η παραμονή σου στο Spirit House ολοκληρώνεται εδώ. Ψήφοι: ${counts.map(c=>`${name(c.id)} ${c.n}`).join(' · ')}.${tie?` Ο αρχηγός ${name(s.hoh)} έλυσε την ισοψηφία.`:''}`,[out],{votes,evicted:out});s.previous=s.hoh;s.hoh=null;s.nominees=[];s.week++;s.stage='hoh';return e;}
 throw new Error('Unknown stage '+s.stage);
}
